let state;try{state={...structuredClone(initial),...JSON.parse(localStorage.getItem('baan-pos-v1')||'null')}}catch{state=structuredClone(initial)}
let page=state.role==='Auditor / Finance'?'dashboard':'pos',category='ทั้งหมด',query='',list=false,member=null,method='cash',processing=false,reportDate='';
