const navs=[['pos','cart','ขายหน้าร้าน'],['dashboard','grid','ภาพรวมร้านค้า'],['products','box','จัดการสินค้า'],['inventory','stock','คลังสินค้า'],['history','receipt','ประวัติการขาย'],['customers','users','ลูกค้าและสมาชิก'],['promotions','tag','โปรโมชัน'],['reports','chart','รายงานการขาย'],['branches','branch','สาขาและการโอน'],['staff','users','พนักงานและสิทธิ์'],['audit','audit','ประวัติการใช้งาน'],['settings','settings','ตั้งค่าร้านค้า']];
function save(){localStorage.setItem('baan-pos-v1',JSON.stringify(state))}
function log(action,entity,before='',after=''){state.audit.unshift({actor:state.role,action,entity,before,after,branch:state.branch,time:new Date().toISOString()});save()}
function notify(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function stock(p,b=state.branch){return p.stocks?.[b]??p.stock}function setStock(p,n,b=state.branch){p.stocks={...p.stocks,[b]:n}}
