if(p.art==='milk')shape='<path d="M66 33l10-15h27l10 15v79H66z" fill="#faf9ef"/><path d="M66 33h47v79H66z" fill="'+c+'"/><path d="M76 18v15h37l-10-15" fill="#dce2d0"/><rect x="72" y="51" width="35" height="42" rx="2" fill="#f4f3de"/><path d="M84 71c-8-6-2-13 5-6 6-8 14-1 6 6l-6 7z" fill="'+c+'"/><text x="89" y="86" text-anchor="middle" font-size="7" fill="#6b795c" font-family="serif">ORGANIC</text>';
