function canManage(){return ['Owner / Admin','Store Manager','HQ / Operations'].includes(state.role)}
function allowed(p){if(state.role==='Cashier')return ['pos','products','inventory','history','customers','promotions'].includes(p);if(state.role==='Auditor / Finance')return ['dashboard','reports','history','audit'].includes(p);if(p==='settings'||p==='staff')return state.role==='Owner / Admin';return true}
function navigate(p){if(!allowed(p)){notify('ไม่มีสิทธิ์เข้าถึง · กรุณาสลับบทบาทที่โปรไฟล์');return}page=p;query='';render()}
function nav(n){return '<button class="'+(page===n[0]?'active':'')+'" onclick="navigate(\''+n[0]+'\')" title="'+n[2]+'">'+icon(n[1])+'<span>'+n[2]+'</span>'+(n[0]==='inventory'?'<em>'+state.products.filter(p=>stock(p)<=5).length+'</em>':'')+'</button>'}
function render(){save();$('#app').innerHTML='<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">'+icon('shop',24)+'</span><span>BAAN<span> POS</span></span></div><button class="workspace" onclick="login()"><span class="store-icon">'+icon('shop',17)+'</span><span>บ้าน · ร้านของเรา<br><small>สาขา'+esc(state.branch)+'</small></span>'+icon('down',13)+'</button><div class="navlabel">WORKSPACE</div><nav class="nav">'+navs.slice(0,7).map(nav).join('')+'<div class="nav-divider"></div><div class="navlabel">MANAGEMENT</div>'+navs.slice(7).map(nav).join('')+'</nav><div class="sidebottom"><div class="help">'+icon('help',17)+' ให้เราช่วยคุณไหม?<p>คู่มือเล็ก ๆ สำหรับวันทำงานที่ง่ายขึ้น</p><button onclick="help()">ศูนย์ช่วยเหลือ ↗</button></div><button class="profile" onclick="login()"><div class="avatar">กจ</div><div><strong>กมลชนก ใจดี</strong><small>'+esc(state.role)+'</small></div>'+icon('down',13)+'</button></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">เวิร์กสเปซ '+icon('chevron',11)+'<strong>'+navs.find(n=>n[0]===page)[2]+'</strong></div><div class="top-actions"><span class="status"><i class="dot"></i> ระบบพร้อมใช้งาน</span><span class="date">22 ต.ค. 2026</span><span class="demo">DEMO MODE</span><button class="iconbtn" aria-label="แจ้งเตือน" onclick="navigate(\'inventory\')">'+icon('bell',17)+'</button><select class="branch" aria-label="สาขา" onchange="changeBranch(this.value)">'+['อารีย์','ทองหล่อ','สาทร'].map(b=>'<option '+(state.branch===b?'selected':'')+'>'+b+'</option>').join('')+'</select></div></header><div id="network"></div><div class="page"><div class="pagehead"><div><div class="eyebrow">'+(page==='pos'?'LET’S MAKE A GOOD SALE':'YOUR EVERYDAY, SIMPLIFIED')+'</div><h1>'+navs.find(n=>n[0]===page)[2]+'</h1><p class="subtitle">'+(page==='pos'?'ทุกการขาย เริ่มต้นสิ่งดี ๆ ให้ร้านของคุณ':'จัดการร้านของคุณให้ง่ายขึ้น ในที่เดียว')+'</p></div>'+(page==='pos'?'<button class="outline" onclick="shiftDialog()">'+icon('clock',15)+' '+(state.shift?'กะเช้า · เปิดกะ 08:00':'ยังไม่เปิดกะ')+' '+icon('down',12)+'</button>':'<span class="pill">สาขา'+esc(state.branch)+'</span>')+'</div>'+content()+'<div class="bottom-bar"><span>'+icon('wifi',12)+' บันทึกอัตโนมัติบนอุปกรณ์นี้</span><span>BAAN POS · A little more organized. A lot more you.</span></div></div></main></div>';network();if(page==='pos')$('#search').oninput=e=>{query=e.target.value;$('#products').innerHTML=productCards();$('#product-count').textContent='('+filteredProducts().length+' รายการ)'};if($('#table-search'))$('#table-search').oninput=e=>document.querySelectorAll('tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()))}
function content(){return ({pos,dashboard,products:productsPage,inventory,history:historyPage,customers,promotions,reports:dashboard,branches,staff,audit,settings}[page])()}
function changeBranch(b){if(state.cart.length&&!confirm('เปลี่ยนสาขาและล้างตะกร้าปัจจุบัน?')){render();return}state.branch=b;state.cart=[];state.discount=0;member=null;render();notify('เปลี่ยนเป็นสาขา'+b)}
function pos(){return '<div class="sale-layout"><section><div class="searchrow"><label class="search">'+icon('search',17)+'<input id="search" aria-label="ค้นหาสินค้า" placeholder="ค้นหาชื่อสินค้า, SKU หรือสแกนบาร์โค้ด..."><kbd>⌘ K</kbd></label><button class="scan" onclick="scan()">'+icon('scan',19)+' สแกนสินค้า</button></div><div class="categories">'+cats.map((c,i)=>'<button class="category '+(category===c?'active':'')+'" onclick="selectCategory('+i+')">'+c+' <span>'+(i?state.products.filter(p=>p.cat===c).length:state.products.length)+'</span></button>').join('')+'</div><div class="catalog-head"><span>สินค้าทั้งหมด <small id="product-count">('+filteredProducts().length+' รายการ)</small></span><div class="view-switch"><button aria-label="มุมมองตาราง" class="'+(!list?'active':'')+'" onclick="list=false;render()">'+icon('grid',14)+'</button><button aria-label="มุมมองรายการ" class="'+(list?'active':'')+'" onclick="list=true;render()">'+icon('list',15)+'</button></div></div><div id="products" class="products '+(list?'list-mode':'')+'">'+productCards()+'</div><div class="catalog-footer"><span>แสดงสินค้าพร้อมขาย · สาขา'+esc(state.branch)+'</span><span>ราคาสินค้ารวม VAT '+state.tax+'% แล้ว</span></div></section><aside class="cart" id="cart">'+cartHTML()+'</aside></div>'}
function selectCategory(i){category=cats[i];render()}
function filteredProducts(){return state.products.filter(p=>(category==='ทั้งหมด'||p.cat===category)&&(p.name+' '+p.sub+' '+p.sku+' '+p.barcode).toLowerCase().includes(query.toLowerCase()))}
function productCards(){const ps=filteredProducts();return ps.length?ps.map(p=>'<button class="product" onclick="add('+p.id+')" aria-label="เพิ่ม '+esc(p.name)+'"><div class="product-art" style="background:'+p.bg+'"><span class="badge '+(stock(p)<=5?'low':'')+'">'+(stock(p)===0?'หมดชั่วคราว':stock(p)<=5?'เหลือ '+stock(p)+' ชิ้น':'คงเหลือ '+stock(p))+'</span>'+art(p)+'</div><div class="product-info"><h3>'+esc(p.name)+'</h3><small>'+esc(p.sub)+'</small><div class="product-price"><strong>฿'+money(p.price)+'</strong><span class="add">'+icon('plus',15)+'</span></div></div></button>').join(''):'<div class="empty">'+icon('search',30)+'ไม่พบสินค้า ลองค้นหาด้วยคำอื่น</div>'}
function totals(){const subtotal=Math.round(state.cart.reduce((a,c)=>a+state.products.find(p=>p.id===c.id).price*c.qty,0)*100)/100,discount=Math.min(state.discount,subtotal),total=Math.round((subtotal-discount)*100)/100,tax=Math.round(total*state.tax/(100+Number(state.tax))*100)/100;return {subtotal,discount,total,tax}}
function cartHTML(){const t=totals(),count=state.cart.reduce((a,c)=>a+c.qty,0);return '<div class="cart-head"><div><h2>รายการขาย <span class="count">'+count+'</span></h2><small>#NEW-'+String(state.sales.length+1).padStart(4,'0')+' · '+esc(member?.name||'ลูกค้าทั่วไป')+'</small></div><button class="iconbtn" aria-label="ล้างตะกร้า" onclick="clearCart()">'+icon('trash',17)+'</button></div><button class="customer-pick" onclick="pickCustomer()">'+icon('user',17)+'<span>'+esc(member?.name||'เพิ่มลูกค้า / สมาชิก')+'</span><span>'+icon('plus',13)+'</span></button><div class="cart-items">'+(state.cart.length?state.cart.map(c=>{const p=state.products.find(p=>p.id===c.id);return '<div class="cart-item"><div class="mini-art">'+art(p)+'</div><div><h3>'+esc(p.name)+'</h3><small>฿'+money(p.price)+' / ชิ้น</small><div class="qty"><button aria-label="ลดจำนวน" onclick="quantity('+p.id+',-1)">−</button><span>'+c.qty+'</span><button aria-label="เพิ่มจำนวน" onclick="quantity('+p.id+',1)">+</button></div></div><div class="item-total">฿'+money(p.price*c.qty)+'<button class="remove" aria-label="นำสินค้าออก" onclick="removeItem('+p.id+')">'+icon('close',12)+'</button></div></div>'}).join(''):'<div class="empty">'+icon('cart',32)+'เลือกสินค้าเพื่อเริ่มการขาย<br><small>สินค้าที่เพิ่มจะแสดงที่นี่</small></div>')+'</div><div class="bill-summary"><div><span>ยอดรวมสินค้า ('+count+' ชิ้น)</span><strong>฿'+money(t.subtotal)+'</strong></div><div><button class="discount-button" onclick="discountDialog()">'+icon('tag',12)+' เพิ่มส่วนลด</button><strong style="color:var(--green)">−฿'+money(t.discount)+'</strong></div><div><span>ภาษีมูลค่าเพิ่ม '+state.tax+'% (รวมแล้ว)</span><strong>฿'+money(t.tax)+'</strong></div><div class="grand"><span>ยอดชำระทั้งหมด</span><strong>฿'+money(t.total)+'</strong></div><button class="pay-button" onclick="payment()" '+(!count?'disabled':'')+'><span>'+icon('card',17)+' ชำระเงิน</span><span>฿'+money(t.total)+' '+icon('arrow',15)+'</span></button><div class="cart-bottom"><button class="outline" onclick="hold()">'+icon('pause',12)+' พักบิล'+(state.held.length?' ('+state.held.length+')':'')+'</button><button class="outline" onclick="newBill()">'+icon('plus',13)+' บิลใหม่</button></div><p class="secure">'+icon('audit',10)+' การชำระเงินจำลอง · ไม่มีการเรียกเก็บเงินจริง</p></div>'}
function updateCart(){save();if($('#cart'))$('#cart').innerHTML=cartHTML()}
function add(id){if(!allowed('pos'))return;const p=state.products.find(p=>p.id===id),c=state.cart.find(c=>c.id===id);if((c?.qty||0)>=stock(p)){notify('สินค้าไม่เพียงพอ · คงเหลือ '+stock(p)+' ชิ้น');return}if(c)c.qty++;else state.cart.push({id,qty:1});updateCart()}
function quantity(id,n){if(n>0){add(id);return}const c=state.cart.find(c=>c.id===id);c.qty--;if(!c.qty)state.cart=state.cart.filter(c=>c.id!==id);updateCart()}
function removeItem(id){state.cart=state.cart.filter(c=>c.id!==id);updateCart()}
function clearCart(){if(state.cart.length&&confirm('ยืนยันล้างรายการสินค้าในตะกร้า?')){state.cart=[];state.discount=0;member=null;updateCart()}}
function modal(title,body,foot=''){$('#modal').innerHTML='<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-label="'+esc(title)+'" class="dialog"><div class="dialog-head"><h2>'+title+'</h2><button class="iconbtn" aria-label="ปิด" onclick="closeModal()">'+icon('close',20)+'</button></div>'+body+(foot?'<div class="dialog-foot">'+foot+'</div>':'')+'</section></div>';setTimeout(()=>$('#modal input')?.focus(),40)}
function closeModal(){if(processing)return;$('#modal').innerHTML=''}
function scan(){modal('สแกนสินค้า','<p class="hint">ใส่บาร์โค้ดหรือ SKU แล้วกดเพิ่มสินค้า<br>ตัวอย่าง SKU-001 หรือ 8850000000001</p><form class="form" style="margin-top:15px" onsubmit="event.preventDefault();scanSubmit()"><label>บาร์โค้ด / SKU<input id="barcode" required placeholder="8850000000001"></label><button class="primary">เพิ่มสินค้า</button></form>')}
function scanSubmit(){const q=$('#barcode').value.trim(),p=state.products.find(p=>p.sku===q||p.barcode===q);if(!p){notify('ไม่พบบาร์โค้ดนี้ในระบบ');return}closeModal();add(p.id)}
function discountDialog(){if(!canManage()){notify('ต้องได้รับสิทธิ์ผู้จัดการเพื่อกำหนดส่วนลด');return}modal('ส่วนลดท้ายบิล','<form class="form" onsubmit="event.preventDefault();setDiscount()"><label>ส่วนลด (บาท)<input id="discount" type="number" min="0" max="'+totals().subtotal+'" step=".01" required value="'+state.discount+'"></label><button class="primary">ใช้ส่วนลด</button></form>')}
function setDiscount(){state.discount=Number($('#discount').value);log('เพิ่มส่วนลด','บิลปัจจุบัน','',state.discount);closeModal();updateCart()}
function pickCustomer(){modal('เพิ่มลูกค้า / สมาชิก','<div class="form">'+state.customers.map((c,i)=>'<button class="outline" style="justify-content:space-between" onclick="chooseMember('+i+')"><span>'+esc(c.name)+'<br><small>'+esc(c.phone)+'</small></span><span>'+c.points+' แต้ม</span></button>').join('')+'<button class="soft" onclick="chooseMember(-1)">ลูกค้าทั่วไป</button><button class="primary" onclick="customerDialog(true)">+ สมัครสมาชิกใหม่</button></div>')}
function chooseMember(i){member=state.customers[i]||null;closeModal();updateCart()}
function hold(){if(!state.cart.length){if(!state.held.length){notify('ไม่มีบิลพักไว้');return}modal('บิลที่พักไว้',state.held.map((h,i)=>'<button class="outline" style="width:100%;margin-bottom:8px" onclick="restoreHold('+i+')">บิล '+(i+1)+' · '+h.cart.reduce((a,c)=>a+c.qty,0)+' ชิ้น · สาขา'+esc(h.branch)+'</button>').join(''));return}state.held.push({cart:structuredClone(state.cart),discount:state.discount,branch:state.branch,memberPhone:member?.phone});state.cart=[];state.discount=0;member=null;updateCart();notify('พักบิลแล้ว · กดพักบิลอีกครั้งเพื่อเรียกคืน')}
function restoreHold(i){const h=state.held[i];if(h.branch!==state.branch){notify('กรุณาสลับไปสาขา'+h.branch);return}state.cart=h.cart;state.discount=h.discount;member=state.customers.find(c=>c.phone===h.memberPhone)||null;state.held.splice(i,1);closeModal();updateCart()}
function newBill(){if(state.cart.length){hold();return}state.discount=0;member=null;updateCart();notify('พร้อมเริ่มบิลใหม่')}
function payment(){if(!state.shift){notify('กรุณาเปิดกะก่อนชำระเงิน');shiftDialog();return}if(!state.cart.length)return;method=Object.keys(state.payments).find(k=>state.payments[k]);if(!method){notify('ยังไม่มีช่องทางชำระเงินที่เปิดใช้งาน');return}paymentView()}
function setMethod(k){method=k;paymentView()}
function paymentView(){const t=totals();modal('ชำระเงิน','<div class="payment-total"><small>ยอดชำระทั้งหมด</small><strong>฿'+money(t.total)+'</strong></div><div class="payment-methods">'+[['cash','เงินสด'],['qr','QR พร้อมเพย์'],['card','บัตรจำลอง']].filter(([k])=>state.payments[k]).map(([k,v])=>'<button class="'+(method===k?'active':'')+'" onclick="setMethod(\''+k+'\')">'+v+'</button>').join('')+'</div>'+(method==='cash'?'<label class="form">เงินที่รับ (บาท)<input class="input" id="cash" type="number" step=".01" min="0" value="'+t.total+'" oninput="changeCash()"></label><div class="quickcash">'+[t.total,100,500,1000].filter((v,i,a)=>v>=t.total&&a.indexOf(v)===i).map(v=>'<button onclick="quickCash('+v+')">฿'+money(v)+'</button>').join('')+'</div><p class="hint" id="change" style="margin-top:15px">เงินทอน ฿0.00</p>':method==='qr'?'<div style="text-align:center;border:1px dashed #cbd8c5;padding:20px;border-radius:8px"><div style="font-size:27px;letter-spacing:5px">▦ ▧ ▦<br>▥ ▦ ▥<br>▦ ▧ ▦</div><p class="hint" style="margin-top:8px">QR จำลองสำหรับสาธิตเท่านั้น<br>ไม่มีข้อมูลรับเงินจริง</p></div>':'<p class="hint">เครื่องอ่านบัตรจำลองพร้อมแล้ว<br>ไม่มีการขอหรือจัดเก็บข้อมูลบัตรจริง</p>')+'<label class="hint" style="display:block;margin-top:15px"><input id="fail-payment" type="checkbox"> จำลองการชำระเงินล้มเหลว</label><p id="payment-error" class="error" role="alert"></p>','<button class="outline" onclick="closeModal()">ยกเลิก</button><button id="confirm-pay" class="primary" onclick="completePayment()">'+icon('check',16)+' ยืนยันรับชำระ</button>')}
function quickCash(n){$('#cash').value=n;changeCash()}
function changeCash(){const v=Number($('#cash').value)-totals().total;$('#change').textContent=v>=0?'เงินทอน ฿'+money(v):'ยอดเงินยังไม่ครบ ขาด ฿'+money(-v)}
function completePayment(){if(processing)return;const t=totals(),received=method==='cash'?Number($('#cash').value):t.total;if(!Number.isFinite(received)||received<t.total){$('#payment-error').textContent='กรุณาระบุเงินรับให้ครบยอดชำระ';return}if($('#fail-payment').checked){$('#payment-error').textContent='ชำระเงินไม่สำเร็จ · ยังไม่มีการตัดสต๊อก กรุณาลองอีกครั้ง';return}if(state.cart.some(c=>c.qty>stock(state.products.find(p=>p.id===c.id)))){$('#payment-error').textContent='สินค้าคงเหลือไม่พอ กรุณาตรวจสอบตะกร้า';return}processing=true;$('#confirm-pay').disabled=true;$('#confirm-pay').textContent='กำลังบันทึก...';setTimeout(()=>{const sale={id:'BN-'+String(state.sales.length+1).padStart(5,'0'),items:state.cart.map(c=>({...state.products.find(p=>p.id===c.id),qty:c.qty})),...t,received,change:Math.round((received-t.total)*100)/100,method,branch:state.branch,customer:member?.name||'ลูกค้าทั่วไป',customerPhone:member?.phone,time:new Date().toISOString(),refunded:false};state.sales.unshift(sale);for(const c of state.cart){const p=state.products.find(p=>p.id===c.id);setStock(p,stock(p)-c.qty)}if(member)member.points+=Math.floor(t.total/25);state.cart=[];state.discount=0;member=null;log('ขายสินค้า',sale.id,'',sale.total);processing=false;render();receipt(sale)},500)}
function receipt(s){modal('ใบเสร็จรับเงิน','<div class="receipt"><div class="success">'+icon('check',28)+'</div><h3>'+(s.refunded?'คืนสินค้าแล้ว':'ชำระเงินสำเร็จ')+'</h3><p class="hint">'+esc(state.shop)+' · สาขา'+esc(s.branch)+'<br>'+s.id+' · '+new Date(s.time).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'})+'<br>'+esc(s.customer)+'</p><div class="receipt-lines">'+s.items.map(c=>'<p><span>'+esc(c.name)+' × '+c.qty+'</span><span>฿'+money(c.price*c.qty)+'</span></p>').join('')+'<p><span>ส่วนลด</span><span>−฿'+money(s.discount)+'</span></p><p><span>VAT รวมแล้ว</span><span>฿'+money(s.tax)+'</span></p></div><p class="total">฿'+money(s.total)+'</p><p class="hint" style="margin-top:12px">'+({cash:'เงินสด',qr:'QR จำลอง',card:'บัตรจำลอง'}[s.method])+' · รับ ฿'+money(s.received)+' · ทอน ฿'+money(s.change)+'<br>ขอบคุณที่ให้เราเป็นส่วนหนึ่งของวันดี ๆ</p><small>เอกสารจำลองสำหรับทดสอบเท่านั้น</small></div>','<button class="outline" onclick="window.print()">พิมพ์ใบเสร็จ</button><button class="primary" onclick="closeModal()">เสร็จสิ้น</button>')}
function table(headers,rows){return '<div class="table-wrap"><table><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+(rows.length?rows.join(''):'<tr><td colspan="'+headers.length+'" class="empty">ยังไม่มีข้อมูลสำหรับสาขานี้</td></tr>')+'</tbody></table></div>'}
function toolbar(action=''){return '<div class="searchrow"><label class="search">'+icon('search',16)+'<input id="table-search" placeholder="ค้นหารายการ..." aria-label="ค้นหารายการ"></label>'+action+'</div>'}
function productsPage(){return toolbar('<button class="primary" onclick="productDialog()">+ เพิ่มสินค้า</button>')+table(['สินค้า','SKU / บาร์โค้ด','หมวดหมู่','ราคาขาย','คงเหลือ',''],state.products.map(p=>'<tr><td><strong>'+esc(p.name)+'</strong><br><small>'+esc(p.sub)+'</small></td><td><small>'+esc(p.sku)+'<br>'+esc(p.barcode)+'</small></td><td>'+esc(p.cat)+'</td><td>฿'+money(p.price)+'</td><td>'+stock(p)+'</td><td><button class="soft" onclick="productDialog('+p.id+')">แก้ไข</button></td></tr>'))}
function productDialog(id){if(!canManage()){notify('ต้องได้รับสิทธิ์ผู้จัดการเพื่อแก้ไขสินค้า');return}const p=state.products.find(p=>p.id===id);modal(p?'แก้ไขสินค้า':'เพิ่มสินค้าใหม่','<form class="form" onsubmit="event.preventDefault();saveProduct('+(id||0)+')"><label>ชื่อสินค้า<input id="pname" value="'+esc(p?.name||'')+'" required></label><div class="grid2"><label>ราคา (บาท)<input id="pprice" type="number" min="0" step=".01" value="'+(p?.price||0)+'" required></label><label>หมวดหมู่<select id="pcat">'+cats.slice(1).map(c=>'<option '+(p?.cat===c?'selected':'')+'>'+c+'</option>').join('')+'</select></label></div><label>SKU<input id="psku" value="'+esc(p?.sku||'')+'" required></label><label>บาร์โค้ด<input id="pbarcode" value="'+esc(p?.barcode||'')+'" required></label><label>รายละเอียด / ขนาด<input id="psub" value="'+esc(p?.sub||'')+'" required></label><p id="form-error" class="error"></p><button class="primary">บันทึกสินค้า</button></form>')}
function saveProduct(id){const data={name:$('#pname').value.trim(),price:Number($('#pprice').value),cat:$('#pcat').value,sku:$('#psku').value.trim(),barcode:$('#pbarcode').value.trim(),sub:$('#psub').value.trim()};if(!data.name||state.products.some(p=>p.id!==id&&(p.sku===data.sku||p.barcode===data.barcode))){$('#form-error').textContent='ชื่อสินค้าไม่ถูกต้อง หรือ SKU / บาร์โค้ดซ้ำ';return}const p=state.products.find(p=>p.id===id),before=p?JSON.stringify(p):'';if(p)Object.assign(p,data);else state.products.push({...data,id:Math.max(...state.products.map(p=>p.id))+1,stock:0,art:'bag',bg:'#eeeee5',color:'#8da17a'});log(p?'แก้ไขสินค้า':'เพิ่มสินค้า',data.name,before,JSON.stringify(data));closeModal();render();notify('บันทึกสินค้าเรียบร้อย')}
function inventory(){return '<div class="panel" style="margin:0 0 20px;background:#faf8ec"><strong>สินค้าใกล้หมด '+state.products.filter(p=>stock(p)<=5).length+' รายการ</strong><p class="hint" style="margin-top:5px">ตรวจสอบและเติมสินค้า เพื่อให้ร้านพร้อมขายเสมอ</p></div>'+toolbar()+table(['สินค้า','หมวดหมู่','คงเหลือ','สถานะ','จัดการ'],state.products.map(p=>'<tr><td>'+esc(p.name)+'</td><td>'+esc(p.cat)+'</td><td>'+stock(p)+' ชิ้น</td><td><span class="pill '+(stock(p)<=5?'warn':'')+'">'+(stock(p)===0?'สินค้าหมด':stock(p)<=5?'ใกล้หมด':'พร้อมขาย')+'</span></td><td><button class="soft" onclick="stockDialog('+p.id+')">รับเข้า / ปรับยอด</button></td></tr>'))}
function stockDialog(id){if(!canManage()){notify('ต้องได้รับสิทธิ์ผู้จัดการเพื่อปรับสต๊อก');return}const p=state.products.find(p=>p.id===id);modal('จัดการสต๊อก','<p class="hint">'+esc(p.name)+' · คงเหลือ '+stock(p)+' ชิ้น</p><form class="form" style="margin-top:15px" onsubmit="event.preventDefault();saveStock('+id+')"><label>ประเภท<select id="stocktype"><option value="receive">รับสินค้าเข้า (บวกจากยอดเดิม)</option><option value="adjust">ปรับยอดคงเหลือ</option></select></label><label>จำนวน<input id="stockqty" type="number" min="0" step="1" required></label><label>เหตุผล / เลขที่เอกสาร<input id="stockreason" required></label><button class="primary">ยืนยันบันทึกสต๊อก</button></form>')}
function saveStock(id){const p=state.products.find(p=>p.id===id),before=stock(p),n=Number($('#stockqty').value),type=$('#stocktype').value,reason=$('#stockreason').value;if(!confirm('ยืนยันบันทึกการเปลี่ยนแปลงสต๊อก?'))return;setStock(p,type==='receive'?before+n:n);log('ปรับสต๊อก · '+reason,p.name,before,stock(p));closeModal();render();notify('อัปเดตสต๊อกเรียบร้อย')}
function historyPage(){return toolbar()+table(['เลขที่บิล / เวลา','ลูกค้า','จำนวน','ยอดสุทธิ','สถานะ',''],state.sales.filter(s=>s.branch===state.branch).map((s)=>'<tr><td><strong>'+s.id+'</strong><br><small>'+new Date(s.time).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'})+'</small></td><td>'+esc(s.customer)+'</td><td>'+s.items.reduce((a,c)=>a+c.qty,0)+'</td><td>฿'+money(s.total)+'</td><td><span class="pill '+(s.refunded?'red':'')+'">'+(s.refunded?'คืนเงินแล้ว':'สำเร็จ')+'</span></td><td><button class="soft" onclick="viewReceipt(\''+s.id+'\')">ใบเสร็จ</button> '+(!s.refunded?'<button class="outline" onclick="refundDialog(\''+s.id+'\')">คืนสินค้า</button>':'')+'</td></tr>'))}
function viewReceipt(id){receipt(state.sales.find(s=>s.id===id))}
function refundDialog(id){if(!canManage()){notify('ต้องได้รับอนุมัติจากผู้จัดการเพื่อคืนเงิน');return}const s=state.sales.find(s=>s.id===id);modal('คืนสินค้าและคืนเงิน','<p class="hint">บิล '+s.id+' · คืนทั้งบิล ฿'+money(s.total)+'<br>คืนสินค้าทุกรายการกลับเข้าสต๊อกของสาขา'+esc(s.branch)+'</p><form class="form" style="margin-top:18px" onsubmit="event.preventDefault();refund(\''+id+'\')"><label>เหตุผลการคืน<input id="refundreason" required></label><p class="hint">ผู้อนุมัติ: '+esc(state.role)+'</p><button class="primary">ยืนยันคืนเงินจำลอง</button></form>')}
function refund(id){const s=state.sales.find(s=>s.id===id);if(s.refunded)return;if(!confirm('ยืนยันคืนสินค้าและคืนเงินทั้งบิล?'))return;s.refunded=true;s.refundReason=$('#refundreason').value;s.approver=state.role;for(const c of s.items){const p=state.products.find(p=>p.id===c.id);setStock(p,stock(p,s.branch)+c.qty,s.branch)}const c=state.customers.find(c=>c.phone===s.customerPhone);if(c)c.points=Math.max(0,c.points-Math.floor(s.total/25));log('คืนเงิน · '+s.refundReason,s.id,s.total,0);closeModal();render();notify('คืนเงินและคืนสต๊อกเรียบร้อย')}
function customers(){return toolbar('<button class="primary" onclick="customerDialog()">+ เพิ่มสมาชิก</button>')+table(['สมาชิก','เบอร์โทรศัพท์','คะแนนสะสม','สถานะ'],state.customers.map(c=>'<tr><td>'+esc(c.name)+'</td><td>'+esc(c.phone)+'</td><td>'+c.points+' แต้ม</td><td><span class="pill">สมาชิกทั่วไป</span></td></tr>'))}
function customerDialog(pick=false){modal('สมัครสมาชิก','<form class="form" onsubmit="event.preventDefault();saveCustomer('+pick+')"><label>ชื่อสมาชิก<input id="cname" required></label><label>เบอร์โทรศัพท์<input id="cphone" type="tel" pattern="0[0-9]{9}" placeholder="0812345678" required></label><p class="hint">ทุกยอดซื้อ 25 บาท ได้รับ 1 แต้ม</p><p id="form-error" class="error"></p><button class="primary">บันทึกสมาชิก</button></form>')}
function saveCustomer(pick){const phone=$('#cphone').value;if(state.customers.some(c=>c.phone===phone)){$('#form-error').textContent='เบอร์โทรศัพท์นี้เป็นสมาชิกอยู่แล้ว';return}const c={name:$('#cname').value.trim(),phone,points:0};state.customers.push(c);if(pick)member=c;log('เพิ่มสมาชิก',c.name);closeModal();render();notify('สมัครสมาชิกเรียบร้อย')}
function promotions(){return '<div class="grid2"><div class="panel" style="margin-top:0"><span class="pill">ส่วนลดท้ายบิล</span><h2 style="margin-top:20px">วันดี ๆ ลดให้ ฿20</h2><p class="hint">สำหรับยอดซื้อ 200 บาทขึ้นไป<br>ใช้กับตะกร้าปัจจุบัน · ผู้จัดการและ Admin</p><button class="primary" style="margin-top:22px" onclick="applyPromo()">ใช้โปรโมชันนี้</button></div><div class="panel" style="margin-top:0"><span class="pill">สมาชิก</span><h2 style="margin-top:20px">สะสมความสุข ทุกการซื้อ</h2><p class="hint">ทุก 25 บาท รับ 1 แต้ม<br>เพิ่มสมาชิกที่หน้าขายเพื่อสะสมแต้มอัตโนมัติ</p><button class="outline" style="margin-top:22px" onclick="navigate(\'customers\')">ดูสมาชิกทั้งหมด</button></div></div>'}
function applyPromo(){if(!canManage()){notify('ต้องได้รับอนุมัติส่วนลดจากผู้จัดการ');return}if(totals().subtotal<200){notify('ยอดซื้อยังไม่ถึง 200 บาท');return}state.discount=20;log('ใช้โปรโมชัน','ส่วนลด 20 บาท');navigate('pos');notify('ใช้ส่วนลด 20 บาทแล้ว')}
function staff(){return toolbar('<button class="primary" onclick="staffDialog()">+ เพิ่มพนักงาน</button>')+table(['พนักงาน','บทบาท','สถานะ'],state.staff.map((s,i)=>'<tr><td>'+esc(s.name)+'</td><td><select class="branch" aria-label="บทบาทพนักงาน" onchange="setStaffRole('+i+',this.value)">'+['Cashier','Store Manager','Owner / Admin','HQ / Operations','Auditor / Finance'].map(r=>'<option '+(r===s.role?'selected':'')+'>'+r+'</option>').join('')+'</select></td><td><span class="pill">ใช้งาน</span></td></tr>'))}
function setStaffRole(i,v){const before=state.staff[i].role;state.staff[i].role=v;log('เปลี่ยนสิทธิ์พนักงาน',state.staff[i].name,before,v);notify('บันทึกสิทธิ์แล้ว')}
function staffDialog(){modal('เพิ่มพนักงาน','<form class="form" onsubmit="event.preventDefault();saveStaff()"><label>ชื่อพนักงาน<input id="sname" required></label><label>บทบาท<select id="srole"><option>Cashier</option><option>Store Manager</option><option>Owner / Admin</option></select></label><button class="primary">เพิ่มพนักงาน</button></form>')}
function saveStaff(){state.staff.push({name:$('#sname').value.trim(),role:$('#srole').value});log('เพิ่มพนักงาน',$('#sname').value);closeModal();render();notify('เพิ่มพนักงานแล้ว')}
function dashboard(){const all=state.role==='HQ / Operations';let sales=state.sales.filter(s=>!s.refunded&&(all||s.branch===state.branch)&&(!reportDate||new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok'}).format(new Date(s.time))===reportDate));const total=sales.reduce((a,s)=>a+s.total,0),qty=sales.reduce((a,s)=>a+s.items.reduce((a,c)=>a+c.qty,0),0),hours=[8,10,12,14,16,18,20,22],values=hours.map(h=>sales.filter(s=>Math.floor(Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Bangkok',hour:'2-digit',hour12:false}).format(new Date(s.time)))/2)===h/2).reduce((a,s)=>a+s.total,0)),max=Math.max(1,...values);return '<div class="searchrow"><input class="input" style="max-width:190px" type="date" aria-label="กรองวันที่" value="'+reportDate+'" onchange="reportDate=this.value;render()"><button class="outline" onclick="reportDate=\'\';render()">ทั้งหมด</button><button class="outline" onclick="exportSales()">ส่งออก CSV</button></div><div class="kpis">'+[['ยอดขายสุทธิ','฿'+money(total),'รวมบิลที่ชำระสำเร็จ'],['จำนวนบิล',sales.length,'รายการขายในช่วงที่เลือก'],['ยอดเฉลี่ยต่อบิล','฿'+money(sales.length?total/sales.length:0),'ยอดขาย ÷ จำนวนบิล'],['สินค้าขายออก',qty+' ชิ้น','ไม่รวมรายการคืนสินค้า']].map(k=>'<div class="kpi"><p>'+k[0]+'</p><strong>'+k[1]+'</strong><small>'+k[2]+'</small></div>').join('')+'</div><div class="panel"><h2>แนวโน้มยอดขาย <small>บาท / ช่วงเวลา</small></h2><div class="chart">'+hours.map((h,i)=>'<div class="chart-col"><small>฿'+money(values[i])+'</small><div class="bar" style="height:'+(values[i]?Math.max(6,values[i]/max*150):3)+'px"></div><span>'+h+':00</span></div>').join('')+'</div></div><div class="panel"><h2>ยอดขายแยกตามสาขา</h2>'+table(['สาขา','จำนวนบิลสำเร็จ','ยอดขาย'],(all?['อารีย์','ทองหล่อ','สาทร']:[state.branch]).map(b=>{const a=sales.filter(s=>s.branch===b);return '<tr><td>บ้าน · '+b+'</td><td>'+a.length+'</td><td>฿'+money(a.reduce((a,s)=>a+s.total,0))+'</td></tr>'}))+'</div>'}
function exportSales(){const rows=[['เลขที่บิล','วันที่','สาขา','ยอดขาย','สถานะ'],...state.sales.filter(s=>(state.role==='HQ / Operations'||s.branch===state.branch)&&(!reportDate||new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok'}).format(new Date(s.time))===reportDate)).map(s=>[s.id,s.time,s.branch,s.total,s.refunded?'คืนเงิน':'สำเร็จ'])],csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download='baan-sales.csv';a.click();URL.revokeObjectURL(url);notify('ส่งออกรายงานแล้ว')}
function branches(){return '<div class="grid2">'+['อารีย์','ทองหล่อ','สาทร'].map((b,i)=>'<div class="panel" style="margin-top:0"><span class="pill">'+(i===0?'สาขาหลัก':'สาขา '+(i+1))+'</span><h2 style="margin-top:18px">บ้าน · '+b+'</h2><p class="hint">'+state.products.reduce((a,p)=>a+stock(p,b),0)+' ชิ้นในคลัง · '+state.products.length+' รายการสินค้า</p><button class="outline" style="margin-top:16px" onclick="changeBranch(\''+b+'\')">เลือกสาขานี้</button></div>').join('')+'</div><div class="panel"><h2>โอนสินค้าระหว่างสาขา</h2><p class="hint">สร้างรายการจากสาขา'+esc(state.branch)+' ระบบจะจองสินค้าไว้ก่อน ผู้รับสลับสาขาเพื่อยืนยันรับสินค้า</p><button class="primary" style="margin-top:15px" onclick="transferDialog()">+ สร้างใบโอนสินค้า</button>'+table(['สินค้า','ต้นทาง → ปลายทาง','จำนวน','สถานะ',''],state.transfers.map((t,i)=>'<tr><td>'+esc(t.name)+'</td><td>'+esc(t.from)+' → '+esc(t.to)+'</td><td>'+t.qty+'</td><td><span class="pill '+(t.received?'':'warn')+'">'+(t.received?'รับสินค้าแล้ว':'รอรับสินค้า')+'</span></td><td>'+(!t.received&&t.to===state.branch?'<button class="soft" onclick="receiveTransfer('+i+')">ยืนยันรับ</button>':'')+'</td></tr>'))+'</div>'}
function transferDialog(){modal('สร้างใบโอนสินค้า','<form class="form" onsubmit="event.preventDefault();createTransfer()"><label>สินค้า<select id="tproduct">'+state.products.map(p=>'<option value="'+p.id+'">'+esc(p.name)+' ('+stock(p)+')</option>').join('')+'</select></label><label>สาขาปลายทาง<select id="tbranch">'+['อารีย์','ทองหล่อ','สาทร'].filter(b=>b!==state.branch).map(b=>'<option>'+b+'</option>').join('')+'</select></label><label>จำนวน<input id="tqty" type="number" min="1" step="1" required></label><p id="form-error" class="error"></p><button class="primary">ยืนยันสร้างใบโอน</button></form>')}
function createTransfer(){const p=state.products.find(p=>p.id===Number($('#tproduct').value)),n=Number($('#tqty').value),to=$('#tbranch').value;if(n>stock(p)){$('#form-error').textContent='สินค้าไม่เพียงพอ';return}if(!confirm('ยืนยันโอนสินค้า '+n+' ชิ้นไปสาขา'+to+'?'))return;const before=stock(p);setStock(p,before-n);state.transfers.unshift({id:p.id,name:p.name,qty:n,from:state.branch,to,received:false});log('สร้างใบโอน',p.name,before,before-n);closeModal();render();notify('สร้างใบโอนแล้ว กรุณาให้สาขาปลายทางยืนยันรับ')}
function receiveTransfer(i){const t=state.transfers[i];if(t.received||t.to!==state.branch)return;if(!confirm('ยืนยันรับสินค้า '+t.qty+' ชิ้น?'))return;const p=state.products.find(p=>p.id===t.id),before=stock(p);setStock(p,before+t.qty);t.received=true;log('รับสินค้าโอน',p.name,before,stock(p));render();notify('รับสินค้าเรียบร้อย')}
function audit(){return toolbar()+table(['วันที่ / เวลา','ผู้ดำเนินการ','การกระทำ','รายการ','ก่อน → หลัง'],state.audit.map(a=>'<tr><td><small>'+new Date(a.time).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'})+'<br>'+esc(a.branch)+'</small></td><td>'+esc(a.actor)+'</td><td>'+esc(a.action)+'</td><td>'+esc(a.entity)+'</td><td style="max-width:250px;word-break:break-word"><small>'+esc(a.before)+' → '+esc(a.after)+'</small></td></tr>'))}
function settings(){return '<div class="grid2"><div class="panel" style="margin-top:0"><h2>ข้อมูลร้านค้า</h2><form class="form" onsubmit="event.preventDefault();saveSettings()"><label>ชื่อร้าน<input id="shopname" value="'+esc(state.shop)+'" required></label><label>ภาษีมูลค่าเพิ่ม (%) · ราคารวมภาษี<input id="taxrate" type="number" min="0" max="100" step=".01" value="'+state.tax+'" required></label><h3 style="font-size:12px">ช่องทางชำระเงิน</h3>'+[['cash','เงินสด'],['qr','QR พร้อมเพย์จำลอง'],['card','บัตรจำลอง']].map(([k,v])=>'<label style="display:flex;align-items:center"><input style="width:auto" id="enable-'+k+'" type="checkbox" '+(state.payments[k]?'checked':'')+'> '+v+'</label>').join('')+'<button class="primary">บันทึกการตั้งค่า</button></form></div><div class="panel" style="margin-top:0"><h2>เกี่ยวกับต้นแบบนี้</h2><p class="hint">BAAN POS · Interactive prototype v1.0<br>ภาษาไทย · สกุลเงินบาท · ราคาสินค้ารวม VAT<br><br>ข้อมูลถูกบันทึกในเบราว์เซอร์เครื่องนี้ ใช้สำหรับสาธิตการขายและการจัดการร้าน ไม่มีการเชื่อมรับเงินจริง<br><br>สลับบทบาทเพื่อทดลองการจำกัดสิทธิ์ได้ที่โปรไฟล์มุมล่างซ้าย</p><button class="outline" style="margin-top:20px" onclick="login()">สลับบทบาท / สาขา</button></div></div>'}
function saveSettings(){if(state.role!=='Owner / Admin'){notify('เฉพาะ Owner / Admin เท่านั้นที่แก้ไขการตั้งค่าได้');return}state.shop=$('#shopname').value;state.tax=Number($('#taxrate').value);for(const k of ['cash','qr','card'])state.payments[k]=$('#enable-'+k).checked;log('ตั้งค่าร้าน',state.shop,'',JSON.stringify({tax:state.tax,payments:state.payments}));notify('บันทึกการตั้งค่าแล้ว')}
function login(){modal('เข้าสู่ร้านของคุณ','<p class="hint" style="margin-bottom:20px">เลือกบทบาทและสาขาเพื่อทดลองใช้งานต้นแบบ</p><form class="form" onsubmit="event.preventDefault();applyLogin()"><label>บทบาท<select id="loginrole">'+['Cashier','Store Manager','Owner / Admin','HQ / Operations','Auditor / Finance'].map(r=>'<option '+(state.role===r?'selected':'')+'>'+r+'</option>').join('')+'</select></label><label>สาขา<select id="loginbranch">'+['อารีย์','ทองหล่อ','สาทร'].map(b=>'<option '+(state.branch===b?'selected':'')+'>'+b+'</option>').join('')+'</select></label><p class="hint">โหมดสาธิต ไม่ต้องใช้รหัสผ่าน<br>สิทธิ์นี้เป็นการจำลองบนหน้าจอสำหรับ mockup</p><button class="primary">เข้าสู่ระบบ</button></form>')}
function applyLogin(){const role=$('#loginrole').value,b=$('#loginbranch').value;if(b!==state.branch&&state.cart.length&&!confirm('เปลี่ยนสาขาและล้างตะกร้าปัจจุบัน?'))return;if(b!==state.branch){state.cart=[];state.discount=0;member=null}state.role=role;state.branch=b;if(!allowed(page))page=role==='Auditor / Finance'?'dashboard':'pos';log('เข้าสู่ระบบ',role);closeModal();render();notify('เข้าสู่ระบบด้วยบทบาท '+role)}
function shiftDialog(){modal(state.shift?'กะเช้า · กำลังเปิดใช้งาน':'เปิดกะขาย','<p class="hint">สาขา'+esc(state.branch)+' · '+esc(state.role)+'<br>'+(state.shift?'เริ่มกะ 08:00 · ดูสรุปยอดขายก่อนปิดกะ':'เปิดกะเพื่อเริ่มรับชำระเงิน')+'</p><div class="payment-total" style="margin-top:20px"><small>ยอดขายสำเร็จของสาขา</small><strong>฿'+money(state.sales.filter(s=>s.branch===state.branch&&!s.refunded).reduce((a,s)=>a+s.total,0))+'</strong></div>','<button class="primary" onclick="toggleShift()">'+(state.shift?'ปิดกะขาย':'ยืนยันเปิดกะ')+'</button>')}
function toggleShift(){if(state.shift&&!canManage()){notify('กรุณาให้ผู้จัดการอนุมัติการปิดกะ');return}if(!confirm(state.shift?'ยืนยันปิดกะขาย?':'ยืนยันเปิดกะขาย?'))return;state.shift=!state.shift;log(state.shift?'เปิดกะ':'ปิดกะ',state.branch);closeModal();render()}
function help(){modal('ยินดีต้อนรับสู่ BAAN POS','<div class="hint">1. เลือกสินค้าเพื่อเพิ่มลงตะกร้า และปรับจำนวนด้วยปุ่ม + / −<br>2. เพิ่มสมาชิกหรือส่วนลด แล้วเลือกชำระเงิน<br>3. ทดลองเงินสด, QR หรือบัตร และจำลองการจ่ายล้มเหลว<br>4. ดูใบเสร็จหรือคืนสินค้าที่เมนูประวัติการขาย<br>5. รับสินค้าเข้าหรือโอนสาขาที่เมนูคลังสินค้าและสาขา<br><br>⌘ / Ctrl + K เพื่อค้นหา · Esc เพื่อปิดหน้าต่าง<br>สลับบทบาทและสาขาได้จากโปรไฟล์<br><br><a href="handoff.html" target="_blank" style="color:var(--green)">ดู Sitemap, Wireframe และ Design handoff ↗</a></div>')}
function network(){if($('#network'))$('#network').innerHTML=navigator.onLine?'':'<div class="offline">ออฟไลน์ · ต้นแบบยังใช้งานได้บนอุปกรณ์นี้ ไม่มีการซิงก์กับเซิร์ฟเวอร์</div>'}
window.addEventListener('online',network);window.addEventListener('offline',network);
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#search')?.focus()}if(e.key==='Escape')closeModal()});
render();
